impl Partial<'_> {
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn eof(&self) -> bool {
        self.i >= self.b.len()
    }
    /// `Ok(None)`: the input ended inside this value.
    fn value(&mut self) -> Result<Option<Value>, String> {
        self.ws();
        if self.eof() {
            return Ok(None);
        }
        match self.b[self.i] {
            b'{' => {
                self.i += 1;
                let mut m = Map::new();
                loop {
                    self.ws();
                    if self.eof() {
                        return Ok(Some(Value::Object(m)));
                    }
                    if self.b[self.i] == b'}' {
                        self.i += 1;
                        return Ok(Some(Value::Object(m)));
                    }
                    let Some(Value::String(k)) = self.value()? else { return Ok(Some(Value::Object(m))) };
                    self.ws();
                    if self.eof() {
                        return Ok(Some(Value::Object(m)));
                    }
                    if self.b[self.i] != b':' {
                        return Err("ValueError: expected ':'".into());
                    }
                    self.i += 1;
                    let Some(v) = self.value()? else { return Ok(Some(Value::Object(m))) };
                    m.insert(k, v);
                    self.ws();
                    if self.eof() {
                        return Ok(Some(Value::Object(m)));
                    }
                    match self.b[self.i] {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            return Ok(Some(Value::Object(m)));
                        }
                        _ => return Err("ValueError: expected ',' or '}'".into()),
                    }
                }
            }
            b'[' => {
                self.i += 1;
                let mut a = Vec::new();
                loop {
                    self.ws();
                    if self.eof() {
                        return Ok(Some(Value::Array(a)));
                    }
                    if self.b[self.i] == b']' {
                        self.i += 1;
                        return Ok(Some(Value::Array(a)));
                    }
                    let Some(v) = self.value()? else { return Ok(Some(Value::Array(a))) };
                    a.push(v);
                    self.ws();
                    if self.eof() {
                        return Ok(Some(Value::Array(a)));
